import KeyboardArrowDown from '@mui/icons-material/KeyboardArrowDown';
import type { AvatarProps } from '@mui/material/Avatar';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import { useFormControl } from '@mui/material/FormControl';
import MenuItem, { type MenuItemProps } from '@mui/material/MenuItem';
import type { OutlinedInputProps } from '@mui/material/OutlinedInput';
import Select, { type SelectProps } from '@mui/material/Select';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import {
  Children,
  cloneElement,
  isValidElement,
  type Key,
  type ReactNode,
} from 'react';
import { menuItemSx, menuPaperSx } from './menu-paper';
import { SelectOptionContent } from './select-option-content';
import { selectStyles } from './sv-select.styles.ts';

export interface SvSelectOption<Value = unknown> {
  /** Supply a stable key for object values or dynamic option lists. */
  key?: Key;
  value: Value;
  label: ReactNode;
  disabled?: boolean;
  avatar?: AvatarProps;
  slotProps?: { item?: Omit<MenuItemProps, 'value' | 'children' | 'disabled'> };
}

export type SvSelectProps<Value = unknown> = SelectProps<Value> &
  (
    | { children?: ReactNode; options?: never }
    | {
        children?: never;
        options: readonly SvSelectOption<
          Value extends readonly (infer Item)[] ? Item : Value
        >[];
        native?: false | undefined;
      }
  );

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvSelect: SvSelectProps;
  }
  interface Components {
    SvSelect?:
      { defaultProps?: Partial<SvSelectProps> | undefined } | undefined;
  }
}

// React 19 passes ref through props, preserving Select's generic call signature.
export function SvSelect<Value = unknown>(inProps: SvSelectProps<Value>) {
  const muiDefaults = useDefaultProps<SvSelectProps<Value>>({
    props: {},
    name: 'MuiSelect',
  });
  const svDefaults = useDefaultProps<SvSelectProps<Value>>({
    props: {},
    name: 'SvSelect',
  });
  const svProps = useDefaultProps({ props: inProps, name: 'SvSelect' });
  const resolved = useDefaultProps({ props: svProps, name: 'MuiSelect' });
  const {
    className,
    sx: _sx,
    MenuProps,
    IconComponent,
    children: _children,
    options: _options,
    ...props
  } = resolved;
  const contentProps = [inProps, svDefaults, muiDefaults].find(
    (value) => value.children !== undefined || value.options !== undefined
  );
  const options = contentProps?.options;
  // Data options use the MUI menu even if a theme defaults to native Select.
  const native = options === undefined ? props.native : false;
  const children =
    options !== undefined
      ? options.map((option, index) => (
          <MenuItem
            {...option.slotProps?.item}
            key={
              option.key ??
              (typeof option.value === 'string' ||
              typeof option.value === 'number'
                ? option.value
                : index)
            }
            // MUI Select accepts object values, but MenuItem's DOM value type does not.
            value={option.value as MenuItemProps['value']}
            disabled={option.disabled}
          >
            {option.avatar ? (
              <SelectOptionContent
                label={option.label}
                avatar={option.avatar}
              />
            ) : (
              option.label
            )}
          </MenuItem>
        ))
      : contentProps?.children;
  const menuItemDefaults = useDefaultProps<MenuItemProps>({
    props: {},
    name: 'MuiMenuItem',
  });
  const formControl = useFormControl();
  const color = props.color ?? formControl?.color ?? 'primary';
  const variant = props.variant ?? formControl?.variant ?? 'outlined';
  const size = props.size ?? formControl?.size ?? 'medium';
  const customInput = isValidElement<OutlinedInputProps>(props.input)
    ? props.input.props
    : undefined;
  const paperSlotProps = MenuProps?.slotProps?.paper;

  return (
    <Select<Value>
      {...props}
      native={native}
      IconComponent={IconComponent ?? (native ? undefined : KeyboardArrowDown)}
      className={clsx('SvSelect-root', className)}
      sx={mergeSx(
        !props.input &&
          !native &&
          variant === 'outlined' &&
          size === 'medium' &&
          selectStyles(color, props.label != null),
        muiDefaults.sx,
        svDefaults.sx,
        !props.slotProps && customInput?.slotProps?.root?.sx,
        customInput?.sx,
        props.slotProps?.root?.sx,
        inProps.sx
      )}
      MenuProps={
        MenuProps?.slots?.paper
          ? MenuProps
          : {
              ...MenuProps,
              slotProps: {
                ...MenuProps?.slotProps,
                paper: (ownerState) => {
                  const paperProps =
                    typeof paperSlotProps === 'function'
                      ? paperSlotProps(ownerState)
                      : paperSlotProps;
                  return {
                    ...paperProps,
                    sx: mergeSx(menuPaperSx, paperProps?.sx),
                  };
                },
              },
            }
      }
    >
      {native
        ? children
        : Children.map(children, (child) =>
            isValidElement<MenuItemProps>(child) && child.type === MenuItem
              ? cloneElement(child, {
                  sx: mergeSx(menuItemSx, menuItemDefaults.sx, child.props.sx),
                })
              : child
          )}
    </Select>
  );
}

SvSelect.muiName = Select.muiName;
